/**
 * ClientSDK `knowledge` namespace.
 *
 * Wraps `search_memory`, `saveContent` (save_memory),
 * `getContent` (read_knowledge), and `deleteContent` (delete_knowledge).
 * The SDK surface mirrors the MCP tool surface for consistency.
 */

import type { Env } from "../../index";
import { deleteContent } from "../../tools/delete_content";
import { getContent } from "../../tools/get_content";
import type { ToolContext } from "../../tools/registry";
import { saveContent } from "../../tools/save_content";
import { search } from "../../tools/search";

export interface KnowledgeSearchInput {
	query?: string;
	entity_type?: string;
	entity_id?: number;
	parent_id?: number;
	market?: string;
	category?: string;
	fuzzy?: boolean;
	min_similarity?: number;
	include_connections?: boolean;
	include_content?: boolean;
	limit?: number;
}

export interface KnowledgeSaveInput {
	entity_ids?: number[];
	content: string;
	semantic_type: string;
	metadata?: Record<string, unknown>;
	title?: string;
	slug?: string;
}

export interface KnowledgeReadInput {
	/** Fetch specific content events by id. */
	content_ids?: number[];
	/** Fetch knowledge for a watcher window (prompt rendering). */
	watcher_id?: number;
	since?: string;
	until?: string;
	limit?: number;
	before_occurred_at?: string;
	before_id?: number;
	entity_ids?: number[];
}

export type KnowledgeDeleteInput =
	| number
	| { event_id?: number; event_ids?: number[]; reason?: string };

export interface KnowledgeNamespace {
	search(input: KnowledgeSearchInput): Promise<unknown>;
	save(input: KnowledgeSaveInput): Promise<unknown>;
	read(input: KnowledgeReadInput): Promise<unknown>;
	delete(input: KnowledgeDeleteInput): Promise<unknown>;
}

export function buildKnowledgeNamespace(
	ctx: ToolContext,
	env: Env,
): KnowledgeNamespace {
	return {
		search(input) {
			return search(input as never, env, ctx) as Promise<unknown>;
		},
		save(input) {
			return saveContent(input as never, env, ctx) as Promise<unknown>;
		},
		read(input) {
			return getContent(input as never, env, ctx) as Promise<unknown>;
		},
		delete(input) {
			const args =
				typeof input === "number" ? { event_id: input } : (input ?? {});
			return deleteContent(args as never, env, ctx) as Promise<unknown>;
		},
	};
}

/**
 * ClientSDK `entities` namespace.
 *
 * Delegates to `manageEntity` with action-discriminated payloads. Per-call auth
 * checks fire inside the handler; this wrapper does not duplicate them.
 */

import type { Env } from "../../index";
import { manageEntity } from "../../tools/admin/manage_entity";
import type { ToolContext } from "../../tools/registry";
import { search } from "../../tools/search";
import { createActionCaller } from "./action-call";

export interface EntityListFilter {
	entity_type?: string;
	search?: string;
	limit?: number;
	offset?: number;
	sort_by?: string;
	sort_order?: "asc" | "desc";
	category?: string;
	main_market?: string;
	market?: string;
}

export interface EntityCreateInput {
	type: string;
	name: string;
	slug?: string;
	content?: string;
	parent_id?: number;
	metadata?: Record<string, unknown>;
	enabled_classifiers?: string[];
}

export interface EntityUpdateInput {
	entity_id: number;
	name?: string;
	slug?: string;
	content?: string;
	metadata?: Record<string, unknown>;
	enabled_classifiers?: string[];
	/** Optional note explaining a human correction; stored on the per-field
	 *  ownership marker for the metadata fields this update sets. */
	field_note?: string;
}

export interface EntityLinkInput {
	from_entity_id: number;
	to_entity_id: number;
	relationship_type_slug: string;
	metadata?: Record<string, unknown>;
}

export interface EntitiesNamespace {
	manage(input: Record<string, unknown>): Promise<unknown>;
	list(filter?: EntityListFilter): Promise<unknown>;
	get(input: { entity_id: number }): Promise<unknown>;
	create(input: EntityCreateInput): Promise<unknown>;
	update(input: EntityUpdateInput): Promise<unknown>;
	delete(input: {
		entity_id: number;
		force_delete_tree?: boolean;
	}): Promise<unknown>;
	link(input: EntityLinkInput): Promise<unknown>;
	unlink(input: {
		from_entity_id: number;
		to_entity_id: number;
		relationship_type_slug: string;
	}): Promise<unknown>;
	updateLink(input: {
		from_entity_id: number;
		to_entity_id: number;
		relationship_type_slug: string;
		metadata?: Record<string, unknown>;
	}): Promise<unknown>;
	listLinks(input: {
		entity_id: number;
		relationship_type_slug?: string;
		limit?: number;
		offset?: number;
	}): Promise<unknown>;
	search(query: string, options?: { limit?: number }): Promise<unknown>;
}

export function buildEntitiesNamespace(
	ctx: ToolContext,
	env: Env,
): EntitiesNamespace {
	const { manage, action } = createActionCaller(manageEntity, env, ctx, "entities");

	return {
		manage,
		list(filter) {
			return action("list", filter);
		},
		get(input) {
			return action("get", input);
		},
		create(input) {
			return action("create", {
				entity_type: input.type,
				name: input.name,
				slug: input.slug,
				content: input.content,
				parent_id: input.parent_id,
				metadata: input.metadata,
				enabled_classifiers: input.enabled_classifiers,
			});
		},
		update(input) {
			return action("update", input);
		},
		delete(input) {
			return action("delete", input);
		},
		link(input) {
			return action("link", input);
		},
		unlink(input) {
			return action("unlink", input);
		},
		updateLink(input) {
			return action("update_link", input);
		},
		listLinks(input) {
			return action("list_links", input);
		},
		search(query, options) {
			return search(
				{ query, limit: options?.limit } as never,
				env,
				ctx,
			) as Promise<unknown>;
		},
	};
}

/**
 * ClientSDK `classifiers` namespace. Thin wrapper over `manageClassifiers`.
 *
 * Most CRUD actions use `classifier_id: number`; `classify` uses
 * `classifier_slug: string`. The namespace keeps those distinct.
 */

import type { Env } from "../../index";
import { manageClassifiers } from "../../tools/admin/manage_classifiers";
import type { ToolContext } from "../../tools/registry";
import { createActionCaller } from "./action-call";

export interface ClassifierCreateInput {
	slug: string;
	name: string;
	description?: string;
	attribute_key: string;
	attribute_values?: Record<
		string,
		{
			description: string;
			examples: string[];
			embedding?: number[] | null;
		}
	>;
	entity_id?: number;
	watcher_id: string;
	min_similarity?: number;
	fallback_value?: unknown;
	created_by?: string;
}

export interface ClassifierClassifyInput {
	classifier_slug: string;
	/** Single-mode update. */
	content_id?: number;
	value?: string | null;
	/** Batch mode. */
	classifications?: Array<{
		content_id: number;
		value: string | null;
		reasoning?: string;
	}>;
	source?: "llm" | "user";
	reasoning?: string;
}

export interface ClassifiersNamespace {
	manage(input: Record<string, unknown>): Promise<unknown>;
	list(input?: { entity_id?: number; status?: string }): Promise<unknown>;
	create(input: ClassifierCreateInput): Promise<unknown>;
	generateEmbeddings(input: {
		classifier_id: number;
		force_regenerate?: boolean;
	}): Promise<unknown>;
	delete(input: { classifier_id: number }): Promise<unknown>;
	classify(input: ClassifierClassifyInput): Promise<unknown>;
}

export function buildClassifiersNamespace(
	ctx: ToolContext,
	env: Env,
): ClassifiersNamespace {
	const { manage, action } = createActionCaller(manageClassifiers, env, ctx, "classifiers");

	return {
		manage,
		list: (input) => action("list", input),
		create: (input) => action("create", input),
		generateEmbeddings: (input) => action("generate_embeddings", input),
		delete: (input) => action("delete", input),
		classify: (input) => action("classify", input),
	};
}

/**
 * ClientSDK `metrics` namespace. Thin wrapper over the metric MCP tools
 * (`list_metrics`, `query_metric`, `metric_series`).
 */

import type { Static } from "@sinclair/typebox";
import type { Env } from "../../index";
import {
	ListMetricsSchema,
	listMetrics,
} from "../../tools/admin/list_metrics";
import {
	MetricSeriesSchema,
	metricSeries,
} from "../../tools/admin/metric_series";
import {
	QueryMetricSchema,
	queryMetric,
} from "../../tools/admin/query_metric";
import type { ToolContext } from "../../tools/registry";

export type MetricsListInput = Static<typeof ListMetricsSchema>;
export type MetricsQueryInput = Static<typeof QueryMetricSchema>;
export type MetricsSeriesInput = Static<typeof MetricSeriesSchema>;

export interface MetricsNamespace {
	list(input?: MetricsListInput): Promise<unknown>;
	query(input: MetricsQueryInput): Promise<unknown>;
	series(input: MetricsSeriesInput): Promise<unknown>;
}

export function buildMetricsNamespace(
	ctx: ToolContext,
	env: Env,
): MetricsNamespace {
	return {
		list: (input) => listMetrics(input ?? {}, env, ctx),
		query: (input) => queryMetric(input, env, ctx),
		series: (input) => metricSeries(input, env, ctx),
	};
}

/**
 * ClientSDK `behaviors` namespace. Thin, action-complete wrapper over
 * `manageBehaviors` + `getBehavior`.
 *
 * Keep this surface in sync with `ManageBehaviorsSchema`: every
 * `manage_behaviors.action` should either have a named SDK method below or be
 * reachable via `behaviors.manage({ action, ... })`.
 */

import type { Env } from "../../index";
import type {
	BehaviorExecutionConfig,
	BehaviorSource,
	BehaviorTrigger,
	ListBehaviorsArgs,
} from "@lobu/core/contracts/tools/manage-behaviors";
import {
	type ManageBehaviorsArgs,
	manageBehaviors,
} from "../../tools/admin/manage_behaviors";
import { getBehavior } from "../../tools/get_behavior";
import type { ToolContext } from "../../tools/registry";
import { createActionCaller } from "./action-call";

type BehaviorId = string;
type BehaviorActionInput = Omit<ManageBehaviorsArgs, "action" | "watcher_id"> & {
	watcher_id?: BehaviorId;
};

export type BehaviorListFilter = ListBehaviorsArgs;

export interface BehaviorCreateInput {
	/** Attach the Behavior to an entity. Omit for an org-scoped/global Behavior. */
	entity_id?: number;
	prompt: string;
	sources?: BehaviorSource[];
	triggers?: BehaviorTrigger[];
	slug?: string;
	name?: string;
	description?: string;
	keying_config?: Record<string, unknown>;
	classifiers?: Record<string, unknown>;
	reactions_guidance?: string;
	reaction_script?: string;
	agent_id?: string;
	scheduler_client_id?: string;
	model_config?: Record<string, unknown>;
	execution_config?: BehaviorExecutionConfig;
	tags?: string[];
}

export interface BehaviorUpdateInput {
	watcher_id: BehaviorId;
	triggers?: BehaviorTrigger[];
	agent_id?: string;
	scheduler_client_id?: string;
	model_config?: Record<string, unknown>;
	/** `null` clears a previously-saved config back to NULL/defaults. */
	execution_config?: BehaviorExecutionConfig | null;
}

export interface BehaviorCompleteWindowInput {
	watcher_id: BehaviorId;
	/** JWT obtained from read_knowledge(watcher_id, since, until). */
	window_token?: string;
	/** Multiple page JWTs obtained from read_knowledge for the same watcher window. */
	window_tokens?: string[];
	extracted_data: Record<string, unknown>;
	replace_existing?: boolean;
	client_id?: string;
	model?: string;
	run_metadata?: Record<string, unknown>;
	template_version_id?: number;
}

export interface BehaviorCreateVersionInput extends BehaviorActionInput {
	watcher_id: BehaviorId;
}

export interface BehaviorVersionDetailsInput {
	watcher_id: BehaviorId;
	version?: number;
}

export interface BehaviorSubmitFeedbackInput {
	watcher_id: BehaviorId;
	window_id: number;
	corrections: Array<{
		field_path: string;
		mutation?: "set" | "remove" | "add";
		value?: unknown;
		note?: string;
	}>;
}

export interface BehaviorGetFeedbackInput {
	watcher_id: BehaviorId;
	window_id?: number;
	limit?: number;
}

export interface BehaviorCreateFromVersionInput {
	version_id: number;
	entity_ids: number[];
	name_pattern?: string;
}

export interface BehaviorsNamespace {
	/** Raw escape hatch for any manage_behaviors action. Prefer named methods. */
	manage(input: ManageBehaviorsArgs): Promise<unknown>;
	list(filter?: BehaviorListFilter): Promise<unknown>;
	get(input: { watcher_id: BehaviorId }): Promise<unknown>;
	create(input: BehaviorCreateInput): Promise<unknown>;
	update(input: BehaviorUpdateInput): Promise<unknown>;
	createVersion(input: BehaviorCreateVersionInput): Promise<unknown>;
	completeWindow(input: BehaviorCompleteWindowInput): Promise<unknown>;
	trigger(input: { watcher_id: BehaviorId }): Promise<unknown>;
	/** Delete one or more Behaviors. */
	delete(input: { watcher_ids: BehaviorId[] }): Promise<unknown>;
	setReactionScript(input: {
		watcher_id: BehaviorId;
		/** TypeScript source. Empty string removes it. */
		reaction_script: string;
	}): Promise<unknown>;
	getVersions(watcher_id: BehaviorId): Promise<unknown>;
	getVersionDetails(
		input: BehaviorId | BehaviorVersionDetailsInput,
	): Promise<unknown>;
	getComponentReference(): Promise<unknown>;
	submitFeedback(input: BehaviorSubmitFeedbackInput): Promise<unknown>;
	getFeedback(input: BehaviorGetFeedbackInput): Promise<unknown>;
	createFromVersion(input: BehaviorCreateFromVersionInput): Promise<unknown>;
}

function normalizeVersionDetailsInput(
	input: BehaviorId | BehaviorVersionDetailsInput,
): { watcher_id: string; version?: number } {
	if (typeof input === "string") {
		return { watcher_id: input };
	}
	return input;
}

export function buildBehaviorsNamespace(
	ctx: ToolContext,
	env: Env,
): BehaviorsNamespace {
	const { manage, action } = createActionCaller(manageBehaviors, env, ctx, "behaviors");

	return {
		manage: (input) => manage(input as Record<string, unknown>),
		list: (filter) => action("list", filter ?? {}),
		get(input) {
			return getBehavior(
				input as never,
				env,
				ctx,
			) as Promise<unknown>;
		},
		create: (input) => action("create", input),
		update: (input) => action("update", input),
		createVersion: (input) => action("create_version", input),
		completeWindow: (input) => action("complete_window", input),
		trigger: (input) => action("trigger", input),
		delete: (input) => action("delete", input),
		setReactionScript: (input) => action("set_reaction_script", input),
		getVersions: (watcher_id) => action("get_versions", { watcher_id }),
		getVersionDetails: (input) =>
			action("get_version_details", normalizeVersionDetailsInput(input)),
		getComponentReference: () => action("get_component_reference"),
		submitFeedback: (input) => action("submit_feedback", input),
		getFeedback: (input) => action("get_feedback", input),
		createFromVersion: (input) => action("create_from_version", input),
	};
}

/**
 * ClientSDK `operations` namespace. Thin wrapper over `manageOperations`.
 *
 * `execute` is the only method flagged `access: 'external'` — dry-run mode
 * (PR-2) intercepts these calls instead of sending them.
 */

import type { Env } from "../../index";
import { manageOperations } from "../../tools/admin/manage_operations";
import type { ToolContext } from "../../tools/registry";
import { createActionCaller } from "./action-call";

export interface OperationsExecuteInput {
	connection_id: number;
	operation_key: string;
	input?: Record<string, unknown>;
	/**
	 * Watcher provenance when this operation fires from a reaction. Both ids are
	 * numeric.
	 */
	watcher_source?: { watcher_id: number; window_id: number };
}

export interface OperationsNamespace {
	manage(input: Record<string, unknown>): Promise<unknown>;
	listAvailable(input?: {
		connector_key?: string;
		connection_id?: number;
		entity_id?: number;
		kind?: "read" | "write";
		backend?: "local_action" | "mcp_tool" | "http_operation";
		query?: string;
		include_disconnected?: boolean;
		include_input_schema?: boolean;
		include_output_schema?: boolean;
		limit?: number;
		offset?: number;
	}): Promise<unknown>;
	execute(input: OperationsExecuteInput): Promise<unknown>;
	listRuns(input?: {
		connection_id?: number;
		connection_ids?: number[];
		feed_ids?: number[];
		device_worker_id?: string;
		operation_key?: string;
		status?: string;
		approval_status?: string;
		/** Omit to list every run type (sync, action, auth, …). */
		run_types?: string[];
		before_id?: number;
		before_created_at?: string;
		limit?: number;
		offset?: number;
	}): Promise<unknown>;
	getRun(run_id: number): Promise<unknown>;
	approve(input: {
		run_id: number;
		input?: Record<string, unknown>;
	}): Promise<unknown>;
	reject(input: { run_id: number; reason?: string }): Promise<unknown>;
}

export function buildOperationsNamespace(
	ctx: ToolContext,
	env: Env,
): OperationsNamespace {
	const { manage, action } = createActionCaller(
		manageOperations,
		env,
		ctx,
		"operations",
	);

	return {
		manage,
		listAvailable: (input) => action("list_available", input, "listAvailable"),
		execute: (input) => action("execute", input, "execute"),
		listRuns: (input) => action("list_runs", input, "listRuns"),
		getRun: (run_id) => action("get_run", { run_id }, "getRun"),
		approve: (input) => action("approve", input, "approve"),
		reject: (input) => action("reject", input, "reject"),
	};
}

/**
 * Shared visibility rules for SDK method discovery (`search_sdk`) and the
 * sandbox manifest (`query_sdk` / `run_sdk`). Keeps catalog, manifest, and
 * runtime policy aligned on what a caller can actually invoke.
 */

import type { ToolAccessLevel } from "../auth/tool-access";
import type { MethodAccess } from "./method-metadata";

export type SdkDiscoveryMode = "read" | "full";

/** Whether a method should appear for this caller + discovery mode. */
export function sdkMethodVisible(
	methodAccess: MethodAccess,
	callerMax: ToolAccessLevel,
	mode: SdkDiscoveryMode,
): boolean {
	if (mode === "read") return methodAccess === "read";
	if (methodAccess === "read") return true;
	if (methodAccess === "admin") return callerMax === "admin";
	// write | external — member write tier or admin/owner
	return callerMax === "write" || callerMax === "admin";
}

/**
 * SDK manifest enumeration. Lives in its own module so `runScript` can value-
 * import it without pulling `client-sdk.ts`'s full auth/db chain into the test
 * runtime — the run-script-runtime.test.ts CI guard depends on this.
 */

import type { ToolAccessLevel } from "../auth/tool-access";
import { METHOD_METADATA } from "./method-metadata";
import { sdkMethodVisible } from "./sdk-method-access";

export type SDKMode = "read" | "full";

type SDKManifest = {
	topLevel: string[];
	byNamespace: Record<string, string[]>;
};

const manifestCache = new Map<string, SDKManifest>();

function buildSDKManifest(
	mode: SDKMode,
	allowCrossOrg: boolean,
	callerMax: ToolAccessLevel,
): SDKManifest {
	const topLevel: string[] = [];
	if (sdkMethodVisible("read", callerMax, mode)) {
		if (allowCrossOrg) topLevel.push("org");
		topLevel.push("query", "log");
	}

	const byNamespace: Record<string, string[]> = {};
	for (const [path, meta] of Object.entries(METHOD_METADATA)) {
		const dot = path.indexOf(".");
		if (dot === -1) continue;
		if (!sdkMethodVisible(meta.access, callerMax, mode)) continue;
		const ns = path.slice(0, dot);
		(byNamespace[ns] ??= []).push(path.slice(dot + 1));
	}
	return { topLevel, byNamespace };
}

export function enumerateSDKManifest(
	mode: SDKMode,
	options?: { allowCrossOrg?: boolean; maxAccessLevel?: ToolAccessLevel },
): SDKManifest {
	const allowCrossOrg = options?.allowCrossOrg !== false;
	// Callers that omit maxAccessLevel (reaction scripts, tests) expect the
	// historical full manifest. MCP entry points pass the caller tier explicitly.
	const callerMax =
		options?.maxAccessLevel ??
		(mode === "read" ? "read" : "admin");
	const key = `${mode}:${allowCrossOrg ? "1" : "0"}:${callerMax}`;
	let manifest = manifestCache.get(key);
	if (!manifest) {
		manifest = buildSDKManifest(mode, allowCrossOrg, callerMax);
		manifestCache.set(key, manifest);
	}
	return manifest;
}

/**
 * In-process SDK shared by the `query_sdk` / `run_sdk` MCP tools and watcher reactions.
 * `mode: "read"` filters namespaces against `METHOD_METADATA[*].access === "read"`;
 * `allowCrossOrg: false` makes `client.org(...)` throw `CrossOrgAccessDenied`.
 */

import type { Env } from "../index";
import { isAdminOrOwnerRole, isSystemContext } from "../tools/access-control";
import {
	ADMIN_ONLY_QUERYABLE_TABLES,
	SAFE_COLUMN_DEFS,
} from "../utils/table-schema";
import type { ToolContext } from "../tools/registry";
import { raceAbort } from "../utils/race-abort";
import {
	getCachedMembershipRole,
	getCachedOrgBySlug,
	getOrgById,
} from "../workspace/multi-tenant";
import { METHOD_METADATA } from "./method-metadata";
import type { SDKMode } from "./sdk-manifest";

export { enumerateSDKManifest, type SDKMode } from "./sdk-manifest";

import {
	buildAgentsNamespace,
	buildAuthProfilesNamespace,
	buildBehaviorsNamespace,
	buildCatalogNamespace,
	buildClassifiersNamespace,
	buildConnectionsNamespace,
	buildConversationsNamespace,
	buildEntitiesNamespace,
	buildEntitySchemaNamespace,
	buildFeedsNamespace,
	buildKnowledgeNamespace,
	buildMetricsNamespace,
	buildNotificationsNamespace,
	buildOperationsNamespace,
	buildOrganizationsNamespace,
	buildSchedulesNamespace,
	buildViewTemplatesNamespace,
} from "./namespaces";
import type { AgentsNamespace } from "./namespaces/agents";
import type { AuthProfilesNamespace } from "./namespaces/auth-profiles";
import type { CatalogNamespace } from "./namespaces/catalog";
import type { ClassifiersNamespace } from "./namespaces/classifiers";
import type { ConnectionsNamespace } from "./namespaces/connections";
import type { ConversationsNamespace } from "./namespaces/conversations";
import type { EntitiesNamespace } from "./namespaces/entities";
import type { EntitySchemaNamespace } from "./namespaces/entity-schema";
import type { FeedsNamespace } from "./namespaces/feeds";
import type { KnowledgeNamespace } from "./namespaces/knowledge";
import type { MetricsNamespace } from "./namespaces/metrics";
import type { NotificationsNamespace } from "./namespaces/notifications";
import type { OperationsNamespace } from "./namespaces/operations";
import type { OrganizationsNamespace } from "./namespaces/organizations";
import type { ViewTemplatesNamespace } from "./namespaces/view-templates";
import type { SchedulesNamespace } from "./namespaces/schedules";
import type { BehaviorsNamespace } from "./namespaces/behaviors";

export interface ClientSDK {
	agents: AgentsNamespace;
	entities: EntitiesNamespace;
	entitySchema: EntitySchemaNamespace;
	catalog: CatalogNamespace;
	connections: ConnectionsNamespace;
	conversations: ConversationsNamespace;
	feeds: FeedsNamespace;
	authProfiles: AuthProfilesNamespace;
	operations: OperationsNamespace;
	behaviors: BehaviorsNamespace;
	classifiers: ClassifiersNamespace;
	viewTemplates: ViewTemplatesNamespace;
	knowledge: KnowledgeNamespace;
	metrics: MetricsNamespace;
	notifications: NotificationsNamespace;
	organizations: OrganizationsNamespace;
	schedules: SchedulesNamespace;

	org(slugOrId: string): Promise<ClientSDK>;
	query(sql: string): Promise<unknown[]>;
	log(message: string, data?: Record<string, unknown>): void;
}

class SdkError extends Error {
	readonly code: string;
	constructor(code: string, message: string) {
		super(message);
		this.name = code;
		this.code = code;
	}
}

export class AccessDeniedError extends SdkError {
	constructor(message: string) {
		super("AccessDenied", message);
	}
}

export class OrgNotFoundError extends SdkError {
	constructor(message: string) {
		super("OrgNotFound", message);
	}
}

export class CrossOrgAccessDenied extends SdkError {
	constructor(message: string) {
		super("CrossOrgAccessDenied", message);
	}
}

interface ResolvedOrgMembership {
	orgId: string;
	slug: string;
	role: string | null;
	visibility: "public" | "private";
}

export async function resolveOrgMembership(
	slugOrId: string,
	ctx: ToolContext
): Promise<ResolvedOrgMembership> {
	let orgId: string;
	let slug: string;
	let visibility: "public" | "private";

	const bySlug = await getCachedOrgBySlug(slugOrId);
	if (bySlug) {
		orgId = bySlug.id;
		slug = slugOrId;
		visibility = bySlug.visibility === "public" ? "public" : "private";
	} else {
		const byId = await getOrgById(slugOrId);
		if (!byId) {
			throw new OrgNotFoundError(`Organization '${slugOrId}' not found.`);
		}
		orgId = slugOrId;
		slug = byId.slug;
		visibility = byId.visibility === "public" ? "public" : "private";
	}

	const role = await getCachedMembershipRole(orgId, ctx.userId);

	if (visibility === "private" && role === null) {
		throw new AccessDeniedError(
			`You are not a member of organization '${slug}'.`
		);
	}

	return { orgId, slug, role, visibility };
}

interface BuildClientSDKOptions {
	mode?: SDKMode;
	allowCrossOrg?: boolean;
	/**
	 * Forwarded onto every handler's `ToolContext.abortSignal`. Handlers that
	 * opt in (e.g. `query_sql` / `client.query`) race their work against this
	 * signal so the awaiting caller unblocks immediately on script timeout.
	 * The underlying postgres connection isn't cancelled — see
	 * `ToolContext.abortSignal` for the full caveat.
	 */
	abortSignal?: AbortSignal;
}

export function buildClientSDK(
	ctx: ToolContext,
	env: Env,
	opts?: BuildClientSDKOptions
): ClientSDK {
	const mode: SDKMode = opts?.mode ?? "full";
	const allowCrossOrg = opts?.allowCrossOrg ?? ctx.allowCrossOrg ?? false;
	const ctxWithSignal: ToolContext = opts?.abortSignal
		? { ...ctx, abortSignal: opts.abortSignal }
		: ctx;
	ctx = ctxWithSignal;

	const namespaces = {
		agents: buildAgentsNamespace(ctx, env),
		entities: buildEntitiesNamespace(ctx, env),
		entitySchema: buildEntitySchemaNamespace(ctx, env),
		catalog: buildCatalogNamespace(ctx, env),
		connections: buildConnectionsNamespace(ctx, env),
		conversations: buildConversationsNamespace(ctx, env),
		feeds: buildFeedsNamespace(ctx, env),
		authProfiles: buildAuthProfilesNamespace(ctx, env),
		operations: buildOperationsNamespace(ctx, env),
		behaviors: buildBehaviorsNamespace(ctx, env),
		classifiers: buildClassifiersNamespace(ctx, env),
		viewTemplates: buildViewTemplatesNamespace(ctx, env),
		knowledge: buildKnowledgeNamespace(ctx, env),
		metrics: buildMetricsNamespace(ctx, env),
		notifications: buildNotificationsNamespace(ctx, env),
		organizations: buildOrganizationsNamespace(ctx),
		schedules: buildSchedulesNamespace(ctx, env),
	};

	if (mode === "read") {
		for (const [ns, namespace] of Object.entries(namespaces)) {
			// Drop methods missing a metadata entry or marked write/external.
			// The Proxy in run-script.ts then advertises only the survivors.
			const record = namespace as unknown as Record<string, unknown>;
			for (const method of Object.keys(record)) {
				if (METHOD_METADATA[`${ns}.${method}`]?.access !== "read") {
					delete record[method];
				}
			}
			Object.freeze(namespace);
		}
	}

	const sdk: ClientSDK = {
		...namespaces,

		async org(slugOrId) {
			if (!allowCrossOrg) {
				throw new CrossOrgAccessDenied(
					"Cross-org access is not available on this connection. Use the unscoped /mcp endpoint with an OAuth session, or reconnect to /mcp/{slug} for the target workspace."
				);
			}
			const member = await resolveOrgMembership(slugOrId, ctx);
			return buildClientSDK(
				{ ...ctx, organizationId: member.orgId, memberRole: member.role },
				env,
				{ mode, allowCrossOrg, abortSignal: ctx.abortSignal }
			);
		},

		async query(querySql) {
			// Read-tier parity with `query_sql` / `metric_series`: members may query
			// operational tables; auth/identity tables stay admin-only per-query.
			const isAdmin = isAdminOrOwnerRole(ctx.memberRole);
			const [{ getDb }, { validateAndScopeQuery }] = await Promise.all([
				import("../db/client"),
				import("../utils/execute-data-sources"),
			]);
			const scoped = validateAndScopeQuery(querySql, ctx.organizationId, {
				userId: ctx.userId,
				safeColumns: isSystemContext(ctx) ? undefined : SAFE_COLUMN_DEFS,
				restrictedTables:
					isSystemContext(ctx) || isAdmin
						? undefined
						: ADMIN_ONLY_QUERYABLE_TABLES,
			});
			const rows = await raceAbort(
				getDb().begin(async (tx) => {
					await tx.unsafe("SET TRANSACTION READ ONLY");
					await tx.unsafe("SET LOCAL statement_timeout = '5000'");
					return tx.unsafe(scoped.sql, scoped.params as unknown[]);
				}),
				ctx.abortSignal
			);
			return rows.map((r: Record<string, unknown>) => ({ ...r }));
		},

		log(message, data) {
			// biome-ignore lint/suspicious/noConsole: structured-log fallback; routes through Sentry breadcrumbs in prod.
			console.log(`[client-sdk] ${message}`, data ?? {});
		},
	};

	if (mode === "read") Object.freeze(sdk);
	return sdk;
}

/**
 * ClientSDK method metadata, keyed by dotted path. Drives the `search_sdk` MCP
 * tool, the read-only SDK filter (`access`), and the BANNED_PATHS guard.
 */

export type MethodAccess = "read" | "write" | "external" | "admin";

export interface MethodMetadata {
	summary: string;
	access: MethodAccess;
	/** Exact callable signature when the method shape is easy to misinfer. */
	signature?: string;
	throws?: readonly string[];
	/** Single-line copy-pasteable snippet. */
	example?: string;
	/** Multi-line example surfaced by `search_sdk` for hot-path methods. */
	usageExample?: string;
	/** Cost hint: 'cheap' | 'normal' | 'expensive'. Normal if omitted. */
	cost?: "cheap" | "normal" | "expensive";
}

/** Runtime helpers passed through `ctx`, not dispatchable ClientSDK methods. */
export const RUNTIME_HELPER_METADATA: Record<string, MethodMetadata> = {
	"ctx.sleep": {
		summary:
			"Pause a sandbox script for 0–30000ms. The wait aborts at the script's overall timeout; use it between SDK reads when polling.",
		access: "read",
		example: "await ctx.sleep(1000);",
		usageExample: `// Poll a run without exposing unrestricted timer globals.
export default async (ctx, client) => {
  for (let attempt = 0; attempt < 10; attempt++) {
    const run = await client.operations.getRun(123);
    if (run.status !== 'pending') return run;
    await ctx.sleep(1000);
  }
  throw new Error('Run did not finish in time');
};`,
	},
};

