export const getContent = withValidatedArgs('read_knowledge', GetContentSchema, getContentImpl);

async function getContentImpl(
  args: GetContentArgs,
  env: Env,
  ctx: ToolContext
): Promise<GetContentResult> {
  // SDK delegates (`client.knowledge.get`/`read`) skip `checkToolAccess`, so
  // re-enforce the mcp:read scope here — but only for MCP token callers
  // (oauth/pat). Session/anonymous/system callers carry no MCP scope dimension
  // (they're gated by member role + public-readability at the query level), which
  // mirrors how extractAuthContext assigns scopes: real scopes for oauth/pat, a
  // not-applicable sentinel otherwise.
  const isMcpTokenCaller = ctx.tokenType === 'oauth' || ctx.tokenType === 'pat';
  if (isMcpTokenCaller && !hasRequiredMcpScope('read', ctx.scopes)) {
    throw new ToolUserError('read_knowledge requires an MCP session with read access.', 403);
  }

  // Dual client: PG for auth, PG for data
  const pgSql = createDbClientFromEnv(env);
  const sql = getDb();
  const baseUrl = getPublicWebUrl(ctx.requestUrl, ctx.baseUrl);

  // Validate entity access if entity_id provided (auth query stays on PG)
  if (args.entity_id) {
    await requireReadAccess(pgSql, args.entity_id, ctx);
  }

  // Agent/watcher: entity-type read policy (same envelope as manage_entity /
  // search_memory). Humans skip — role ACL is separate.
  if (ctx.agentId || ctx.actingWatcherId) {
    const actor = await resolveActingPrincipal(getDb(), {
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      agentId: ctx.agentId,
      sessionWatcherId: ctx.actingWatcherId ?? null,
    });
    if (actor.kind !== 'user') {
      const typeSlugs = new Set<string>();
      if (args.entity_types?.length) {
        for (const t of args.entity_types) {
          if (typeof t === 'string' && t.trim()) typeSlugs.add(t.trim());
        }
      }
      if (args.entity_id) {
        const typeRows = await sql`
          SELECT et.slug AS entity_type
          FROM entities e
          JOIN entity_types et ON et.id = e.entity_type_id
          WHERE e.id = ${args.entity_id}
            AND e.organization_id = ${ctx.organizationId}
          LIMIT 1
        `;
        if (typeRows[0]?.entity_type) {
          typeSlugs.add(String(typeRows[0].entity_type));
        }
      }
      for (const slug of typeSlugs) {
        const decision = await evaluateEntityMutation({
          organizationId: ctx.organizationId,
          principalKind: actor.kind,
          principalId: actor.id,
          ownerAgentId: actor.ownerAgentId,
          ownerResolved: actor.ownerResolved,
          action: 'read',
          entityTypeSlug: slug,
          sql: getDb(),
        });
        if (decision === 'deny') {
          throw new ToolUserError(
            `Policy denies reading entities of type '${slug}' for this principal.`,
            403,
          );
        }
      }
    }
  }
  // Stats are now opt-in: callers must explicitly pass `include_classification=summary`
  // (the Atlas events page used to set this unconditionally, which fired a heavy
  // `WITH matching_content` CTE on every first paint — including empty entities).
  const includeClassificationSummary = !!args.include_classification
    ?.split(',')
    .map((v) => v.trim())
    .includes('summary');

  const limit = args.limit || 50;
  const offset = args.offset || 0;

  try {
    // If watcher_id is provided, use watcher-mode: fetch content for all sources and generate window_token
    if (args.watcher_id) {
      return await handleWatcherMode(args, env, sql, {
        organizationId: ctx.organizationId,
        sourceConversationId: ctx.sourceContext?.conversationId ?? null,
      });
    }

    const entityId = args.entity_id;
    const sinceDate = args.since ? parseDateAlias(args.since).date : null;
    const untilDate = args.until ? toEndOfDay(parseDateAlias(args.until).date) : null;

    // Run org-slug lookup and entity-info lookup in parallel — they're
    // independent and on a high-RTT DB the serial form pays the round-trip
    // twice. view_url builds from both, and we still want it populated for
    // LLM consumers reading `read_knowledge` over MCP.
    const [ownerSlug, entityInfoRaw] = await Promise.all([
      getOrganizationSlug(ctx.organizationId),
      entityId
        ? sql`
          SELECT
            e.id,
            et.slug AS entity_type,
            e.slug,
            e.parent_id,
            parent.slug as parent_slug,
            pet.slug as parent_entity_type,
            e.organization_id
          FROM entities e
          JOIN entity_types et ON et.id = e.entity_type_id
          LEFT JOIN entities parent ON e.parent_id = parent.id
          LEFT JOIN entity_types pet ON pet.id = parent.entity_type_id
          WHERE e.id = ${entityId}
        `
        : Promise.resolve([] as Array<Record<string, unknown>>),
    ]);

    let entityInfo: EntityInfo | null = null;
    if (entityId && entityInfoRaw.length > 0) {
      entityInfo = ownerSlug
        ? {
            ownerSlug,
            entityType: entityInfoRaw[0].entity_type as string,
            slug: entityInfoRaw[0].slug as string,
            parentType: (entityInfoRaw[0].parent_entity_type as string) ?? null,
            parentSlug: (entityInfoRaw[0].parent_slug as string) ?? null,
          }
        : null;
    }

    // Visibility scope is folded into the SQL WHERE clause of every list/count
    // path (chronological list, content_ids, include_superseded, score) via
    // `buildConnectionVisibilityClause`. The legacy two-step "find private
    // connections, then find visible connections" round-trip is gone; events
    // with `connection_id IS NULL` (system events) stay visible to authed and
    // unauthed callers alike.
    const visibilityScope = { organizationId: ctx.organizationId, userId: ctx.userId };

    // Log incoming classification filters for debugging
    if (args.classification_filters) {
      logger.debug(
        { classification_filters: args.classification_filters },
        '[get_content] Received classification_filters'
      );
    }

    const classificationFilters = args.classification_filters
      ? Object.entries(args.classification_filters).flatMap(([slug, values]) =>
          values.map((value) => ({ classifier_slug: String(slug), value: String(value) }))
        )
      : undefined;

    const platformFilters = (args.platforms ?? []).map((p) => String(p).trim()).filter(Boolean);

    let effectiveConnectionIds = args.connection_ids ? [...args.connection_ids] : undefined;

    let didPlatformFilter = false;
    if (platformFilters.length > 0) {
      didPlatformFilter = true;
      const placeholders = platformFilters.map((_, index) => `$${index + 2}`).join(', ');
      // When entity_id is provided, filter connections by feeds targeting that entity.
      // Otherwise, filter by organization.
      const platformQuery = entityId
        ? `SELECT DISTINCT c.id
           FROM connections c
           JOIN feeds f ON f.connection_id = c.id
           WHERE $1 = ANY(f.entity_ids)
             AND c.connector_key IN (${placeholders})
             AND c.deleted_at IS NULL
             AND f.deleted_at IS NULL`
        : `SELECT c.id
           FROM connections c
           WHERE c.organization_id = $1
             AND c.connector_key IN (${placeholders})
             AND c.deleted_at IS NULL`;
      const platformRows = await sql.unsafe(platformQuery, [
        entityId ?? ctx.organizationId,
        ...platformFilters,
      ]);
      const platformConnectionIds = (platformRows as unknown as IdRow[])
        .map((row) => Number(row.id))
        .filter((id) => !Number.isNaN(id));

      if (effectiveConnectionIds && effectiveConnectionIds.length > 0) {
        const platformConnectionSet = new Set(platformConnectionIds);
        effectiveConnectionIds = effectiveConnectionIds.filter((id) =>
          platformConnectionSet.has(id)
        );
      } else {
        effectiveConnectionIds = platformConnectionIds;
      }
    }

    const effectivePlatform = platformFilters.length === 1 ? platformFilters[0] : undefined;
    const shouldReturnEmpty =
      didPlatformFilter && (!effectiveConnectionIds || effectiveConnectionIds.length === 0);

    // Determine query strategy:
    // 0. If content_ids provided -> simple direct query by IDs (bypasses other filters except entity_id)
    // 1. If search query provided -> searchContentByText (chronological feed when sort_by=date+desc)
    // 2. If no query + sort_by=score -> use getNormalizedScoreContent
    // 3. If no query + sort_by=date -> use searchContentByText with date sorting
    let rawContent: ContentRow[];
    let total: number;
    let pageInfo: GetContentResult['page'] = {
      limit,
      offset,
      has_more: false,
    };

    if (shouldReturnEmpty) {
      const result: GetContentResult = {
        content: [],
        total: 0,
        page: {
          limit,
          offset,
          has_more: false,
        },
      };
      if (includeClassificationSummary) {
        result.classification_stats = {};
      }
      if (entityInfo) {
        result.view_url = buildContentUrl(
          entityInfo,
          {
            platform: effectivePlatform,
            since: args.since,
            until: args.until,
          },
          baseUrl
        );
      }
      return result;
    }

    if (args.include_superseded) {
      const validationErrors = getIncludeSupersededValidationErrors(args);
      if (validationErrors.length > 0) {
        throw new Error(
          `include_superseded is only supported for entity-scoped chronological listings: ${validationErrors.join('; ')}`
        );
      }
    }

    if (args.content_ids && args.content_ids.length > 0) {
      ({ rawContent, total, pageInfo } = await fetchByContentIds({
        args,
        sql,
        organizationId: ctx.organizationId,
        visibilityScope,
        limit,
        offset,
      }));
    } else if (args.include_superseded) {
      ({ rawContent, total, pageInfo } = await fetchIncludeSuperseded({
        args,
        sql,
        organizationId: ctx.organizationId,
        entityId,
        effectiveConnectionIds,
        effectivePlatform,
        sinceDate,
        untilDate,
        visibilityScope,
        limit,
        offset,
      }));
    } else if (args.sort_by === 'score' && entityId) {
      logger.info('[get_content] Using sophisticated multi-signal score ranking');

      const filters: Parameters<typeof getNormalizedScoreContent>[3] = {
        ...(effectiveConnectionIds?.length && { connection_ids: effectiveConnectionIds }),
        ...(args.feed_ids?.length && { feed_ids: args.feed_ids }),
        ...(args.run_ids?.length && { run_ids: args.run_ids }),
        ...(effectivePlatform && { platform: effectivePlatform }),
        ...(sinceDate && { since: sinceDate }),
        ...(untilDate && { until: untilDate }),
        ...(args.engagement_min !== undefined && { engagement_min: args.engagement_min }),
        ...(args.engagement_max !== undefined && { engagement_max: args.engagement_max }),
        ...(args.window_id !== undefined && { window_id: args.window_id }),
        ...(args.analyzed_by_watcher_id !== undefined && {
          analyzed_by_watcher_id: args.analyzed_by_watcher_id,
        }),
        ...(args.exclude_watcher_id !== undefined && {
          exclude_watcher_id: args.exclude_watcher_id,
        }),
        ...(classificationFilters?.length && { classification_filters: classificationFilters }),
        ...(args.classification_source && { classification_source: args.classification_source }),
        ...(args.semantic_type && { semantic_type: args.semantic_type }),
        ...(args.interaction_status && { interaction_status: args.interaction_status }),
        visibility_scope: visibilityScope,
      };

      const [contentResult, countResult] = await Promise.all([
        getNormalizedScoreContent(entityId, limit, offset, filters),
        getNormalizedScoreContentCount(entityId, filters),
      ]);

      rawContent = contentResult;
      total = countResult;
      pageInfo = {
        limit,
        offset,
        has_more: offset + rawContent.length < total,
      };
    } else {
      logger.info(`[get_content] ${args.query ? 'Search query provided' : 'Listing content'}`);

      const searchOptions = {
        entity_id: args.entity_id,
        organization_id: !args.entity_id ? ctx.organizationId : undefined,
        connection_ids: effectiveConnectionIds,
        feed_ids: args.feed_ids,
        run_ids: args.run_ids,
        ...(args.agent_id && { agent_id: args.agent_id }),
        visibility_scope: visibilityScope,
        window_id: args.window_id,
        analyzed_by_watcher_id: args.analyzed_by_watcher_id,
        exclude_watcher_id: args.exclude_watcher_id,
        platform: effectivePlatform,
        since: args.since,
        until: args.until,
        engagement_min: args.engagement_min,
        engagement_max: args.engagement_max,
        min_similarity: args.min_similarity,
        include_classifications: true,
        classification_filters: classificationFilters,
        classification_source: args.classification_source,
        semantic_type: args.semantic_type,
        entity_types: args.entity_types,
        interaction_status: args.interaction_status,
        limit,
        offset,
        // When a query is provided and no explicit sort_by, rank by combined_score
        // (text + vector). Defaulting to 'date' here quietly bypasses semantic ranking
        // and orders results newest-first, which is not what most semantic callers want.
        // Callers can still request chronological by passing sort_by='date' explicitly.
        sort_by: args.sort_by || (args.query ? 'score' : 'date'),
        sort_order: args.sort_order,
        ...(args.vector_weight !== undefined && { vector_weight: args.vector_weight }),
        before_occurred_at: args.before_occurred_at,
        before_id: args.before_id,
        after_occurred_at: args.after_occurred_at,
        after_id: args.after_id,
      };

      // Primary single-query search. A capable agent already phrases its own
      // search query, so this is the path the vast majority of calls take.
      const result = await searchContentByText(args.query ?? null, searchOptions, env);
      rawContent = result.content;
      total = result.total;
      pageInfo = result.page;

      // Auto recall-rescue: if a score-sorted text query found NOTHING on the
      // first page, the raw phrasing was likely too conversational/underspecified
      // to match. Expand it into LLM-rewritten keyword variants and fuse their
      // hits. Fires ONLY on a total miss, so the common (found-something) path
      // pays no extra LLM call or round-trip. Stateless per-request
      // (multi-replica-safe); date feeds, cursor pages, and deep windows keep
      // single-query semantics. Replaces the old opt-in `rewrite_query` param:
      // callers no longer reason about it — it self-heals on a miss.
      const FALLBACK_FETCH_CAP = 400;
      const fallbackEligible =
        rawContent.length === 0 &&
        !!args.query &&
        (args.sort_by ?? 'score') === 'score' &&
        !args.before_occurred_at &&
        !args.after_occurred_at &&
        offset === 0 &&
        limit <= FALLBACK_FETCH_CAP;
      const variants = fallbackEligible ? await rewriteQueries(args.query as string, env) : [];

      if (variants.length > 0 && args.query) {
        // Over-fetch per variant so fusion has a real candidate pool to re-rank
        // (a variant's best hit may sit past the caller's `limit` in its own
        // ranking), capped so a large caller limit can't fan out into tens of
        // thousands of rows. The raw query already returned nothing, so only the
        // variants are searched here.
        const fetchLimit = Math.min(Math.max(limit * 4, 40), FALLBACK_FETCH_CAP);
        const fusionOptions = { ...searchOptions, limit: fetchLimit, offset: 0 };

        // candidate pool: event id -> best (max-score) row seen across variants.
        const pool = new Map<number, { row: ContentRow; score: number }>();
        const fuseInto = (rows: ContentRow[]) => {
          for (const row of rows) {
            const score = row.combined_score ?? row.similarity ?? 0;
            const existing = pool.get(row.id);
            if (!existing || score > existing.score) {
              pool.set(row.id, { row, score });
            }
          }
        };

        // Sentinel: a variant whose fetch came back full may have more matches
        // beyond the cap, so the pool is a LOWER BOUND on the true fused total
        // and deep pages must not be reported as exhausted.
        let poolTruncated = false;
        for (const variant of variants) {
          const variantResult = await searchContentByText(variant, fusionOptions, env);
          fuseInto(variantResult.content);
          poolTruncated ||= variantResult.content.length >= fetchLimit;
        }

        const ranked = [...pool.values()].sort((a, b) => b.score - a.score).map((c) => c.row);

        // The caller's limit pages out of the FUSED ranking (offset is 0 here).
        rawContent = ranked.slice(0, limit);
        total = ranked.length;
        pageInfo = { limit, offset: 0, has_more: poolTruncated || ranked.length > limit };
      }
    }

    // Optionally fetch classification statistics (aggregated across ALL matching content, not just paginated results)
    let classificationStats: GetContentResult['classification_stats'] | undefined;
    if (includeClassificationSummary) {
      classificationStats = await fetchClassificationStats({
        args,
        sql,
        effectiveConnectionIds,
        effectivePlatform,
        sinceDate,
        untilDate,
        visibilityScope,
      });
    }

    // Fetch excerpts for evidence highlighting when filtering by a single classification value
    const excerptsMap = await fetchClassificationExcerpts(sql, classificationFilters, rawContent);

    // Map to the canonical content item shape used across the app.
    const contentItems: ContentItem[] = await buildContentItems({
      sql,
      rawContent,
      organizationId: ctx.organizationId,
      ownerSlug,
      baseUrl,
      excerptsMap,
    });

    // Stamp a LIVE pending-proposal count onto every change_set card. The
    // change_set event is permanent (it records what the run did), so its
    // batch Approve/Reject buttons must key off the CURRENT run state — not the
    // event itself — or they linger after every proposal is resolved and a
    // second click hits an already-decided run ("Run not found or not pending").
    await stampPendingProposalCounts(sql, ctx.organizationId, contentItems);

    const result: GetContentResult = {
      content: contentItems,
      total,
      page: pageInfo,
    };

    if (classificationStats) {
      result.classification_stats = classificationStats;
    }

    // Add view URL when an entity is in scope. Consumed by LLM agents over MCP.
    if (entityInfo) {
      result.view_url = buildContentUrl(
        entityInfo,
        {
          platform: effectivePlatform,
          since: args.since,
          until: args.until,
        },
        baseUrl
      );
    }

    // Entity summary: when searching org-wide (query provided, no entity_id/watcher_id)
    if (args.query && !args.entity_id && !args.watcher_id && contentItems.length > 0) {
      const entityCountMap = new Map<number, number>();
      for (const item of contentItems) {
        for (const eid of item.entity_ids) {
          entityCountMap.set(eid, (entityCountMap.get(eid) || 0) + 1);
        }
      }

      if (entityCountMap.size > 1) {
        const uniqueEntityIds = Array.from(entityCountMap.keys());
        const idList = `{${uniqueEntityIds.join(',')}}`;
        const entityRows = await sql`
          SELECT e.id, e.name, et.slug AS entity_type
          FROM entities e
          JOIN entity_types et ON et.id = e.entity_type_id
          WHERE e.id = ANY(${idList}::int[])
        `;

        const entitySummary = entityRows
          .map((row: any) => ({
            entity_id: Number(row.id),
            name: row.name as string,
            entity_type: row.entity_type as string,
            result_count: entityCountMap.get(Number(row.id)) || 0,
          }))
          .sort((a, b) => b.result_count - a.result_count)
          .slice(0, 20);

        result.entity_summary = entitySummary;
      }
    }

    // Hints for the client
    const hints: string[] = [];
    if (offset + contentItems.length < total) {
      hints.push(`${total - (offset + contentItems.length)} more results available.`);
    }
    if (result.entity_summary) {
      hints.push(`Results span ${result.entity_summary.length} entities. Use entity_id to focus.`);
    }
    if (hints.length > 0) result.hints = hints;

    return result;
  } catch (error) {
    logger.error({ err: error }, 'get_content error:');
    throw error;
  }
}

/**
 * Tool: metric_series
 *
 * Generic read-only SQL endpoint for dashboard sparklines + stat chips.
 * The caller passes a single SELECT (or WITH … SELECT) returning N columns
 * of time-bucketed values. The query goes through the same
 * `validateAndScopeQuery` guard as `query_sql`, plus a few endpoint-local
 * defense layers:
 *
 *   - prefix check: only `SELECT` or `WITH` are accepted (no DML/DDL prefix)
 *   - validateAndScopeQuery: parser-validated, table allowlist, sensitive
 *     column blocklist, user `$N` rejection, auto-scoped via CTEs that
 *     inject `WHERE organization_id = $1` per referenced table
 *   - server-injected `$1`: caller can't choose which org to query
 *   - statement timeout: 5s, enforced via SET LOCAL inside a transaction
 *   - hard row cap: queries returning more than MAX_ROWS rows are rejected
 *
 * Returns `{ columns: string[], rows: unknown[][] }`. Also exposed as
 * `client.metrics.series` in the ClientSDK and on the MCP agent surface.
 */

import { type Static, Type } from '@sinclair/typebox';
import { getDb } from '../../db/client';
import { isReadQuery, validateAndScopeQuery } from '../../utils/execute-data-sources';
import { ADMIN_ONLY_QUERYABLE_TABLES, SAFE_COLUMN_DEFS } from '../../utils/table-schema';
import { ToolUserError } from '../../utils/errors';
import logger from '../../utils/logger';
import type { ToolContext } from '../registry';
import { withValidatedArgs } from '../validate-args';
import { isAdminOrOwnerRole } from '../access-control';

export const MetricSeriesSchema = Type.Object({
  sql: Type.String({
    description:
      'A single SELECT (or WITH … SELECT) returning a bucket column plus one or more numeric stat columns. Table references are auto-scoped to the caller\'s organization; `$1` is the organization id (injected — do not pass it).',
  }),
});

type MetricSeriesArgs = Static<typeof MetricSeriesSchema>;

// Statement timeout in ms. Dashboards refresh frequently — keep tight.
const STATEMENT_TIMEOUT_MS = 5000;

// Hard cap on returned rows. Sparklines need ≤ ~365; anything orders of
// magnitude larger is misuse or a runaway query, so refuse rather than ship
// megabytes back to the client.
const MAX_ROWS = 2000;


interface MetricSeriesResult {
  columns: string[];
  rows: unknown[][];
}

export const metricSeries = withValidatedArgs('metric_series', MetricSeriesSchema, metricSeriesImpl);

async function metricSeriesImpl(
  args: MetricSeriesArgs,
  _env: unknown,
  ctx: ToolContext
): Promise<MetricSeriesResult> {
  const orgId = ctx.organizationId;
  if (!orgId) {
    throw new Error('metric_series: caller must be scoped to an organization');
  }

  if (!isReadQuery(args.sql)) {
    throw new ToolUserError('metric_series: only SELECT or WITH … SELECT queries are accepted');
  }

  // Members may chart their org's operational data; the auth/identity tables
  // (oauth_tokens, oauth_clients, user) stay admin-only.
  const isAdmin = isAdminOrOwnerRole(ctx.memberRole);
  const { sql: scopedSql, params } = validateAndScopeQuery(args.sql, orgId, {
    // Emit the safe column allowlist (not SELECT *) so a member charting e.g.
    // `connections` can't pull credential columns the allowlist withholds.
    safeColumns: SAFE_COLUMN_DEFS,
    restrictedTables: isAdmin ? undefined : ADMIN_ONLY_QUERYABLE_TABLES,
    // Charts are filtered to the requesting user's connection visibility, so a
    // member can't sparkline another user's private-connection events.
    userId: ctx.userId,
  });
  const db = getDb();

  // Run inside a transaction so SET LOCAL applies for the user query only.
  // `SET LOCAL` doesn't accept prepared parameters, so the timeout literal is
  // interpolated directly (safe — it's a module-level number).
  let rows: Record<string, unknown>[];
  try {
    rows = (await db.begin(async (tx) => {
      // READ ONLY first: a data-modifying CTE (`WITH x AS (DELETE … RETURNING …)
      // SELECT …`) passes the SELECT/WITH guard, so the DB must refuse the write.
      // Mirrors query_sql; without it this read-tier endpoint could mutate.
      await tx.unsafe('SET TRANSACTION READ ONLY');
      await tx.unsafe(`SET LOCAL statement_timeout = ${STATEMENT_TIMEOUT_MS}`);
      return tx.unsafe(scopedSql, params as unknown[]);
    })) as Record<string, unknown>[];
  } catch (err) {
    logger.warn({ err, orgId }, '[metric_series] query failed');
    throw err;
  }

  if (rows.length > MAX_ROWS) {
    throw new ToolUserError(
      `metric_series: query returned ${rows.length} rows (cap ${MAX_ROWS}). Bucket the result further or narrow the time window.`
    );
  }

  // postgres.js returns Array<Record<column, value>>. Flatten to a tabular
  // result so the frontend doesn't have to know column order.
  if (rows.length === 0) {
    return { columns: [], rows: [] };
  }
  const columns = Object.keys(rows[0]);
  const tabular = rows.map((r) => columns.map((c) => r[c]));
  return { columns, rows: tabular };
}

/**
 * Method and sandbox-helper discovery for `query_sdk` / `run_sdk`. Match order:
 * exact path drill-down → namespace prefix listing → substring on path +
 * summary. Client method visibility matches the sandbox dispatch manifests.
 */

import { type Static, Type } from "@sinclair/typebox";
import {
	resolveActingPrincipal,
	resolveWriteEffect,
} from "../authz/entity-policy";
import type { WriteAction } from "../authz/write-action-manifest";
import { resolveMaxAccessLevel } from "../auth/tool-access";
import { getDb } from "../db/client";
import type { Env } from "../index";
import {
	METHOD_METADATA,
	RUNTIME_HELPER_METADATA,
	type MethodMetadata,
} from "../sandbox/method-metadata";
import {
	sdkMethodVisible,
	type SdkDiscoveryMode,
} from "../sandbox/sdk-method-access";
import type { ToolContext } from "./registry";
import { withValidatedArgs } from "./validate-args";
import { searchLiveConnectors } from "./connector-discovery";

/**
 * agents.* paths → agent_config action that must not be blanket-denied for the
 * method to appear in discovery. list/get use read; mutate uses create/update/
 * delete. setSystemAgent is treated as update. manage is raw — hide when every
 * agent_config action is denied at the blanket.
 */
export const AGENTS_SDK_ACTION: Record<string, WriteAction | "any"> = {
	"agents.list": "read",
	"agents.get": "read",
	"agents.create": "create",
	"agents.update": "update",
	"agents.delete": "delete",
	"agents.setSystemAgent": "update",
	"agents.manage": "any",
};

const SDK_DISCOVERY_METADATA: Record<string, MethodMetadata> = {
	...METHOD_METADATA,
	...RUNTIME_HELPER_METADATA,
};

const NAMESPACES = [
	...new Set(
		Object.keys(SDK_DISCOVERY_METADATA)
			.filter((path) => path.includes("."))
			.map((path) => path.split(".")[0])
	),
].sort();

const METADATA_BY_LOWER_PATH = new Map(
	Object.entries(SDK_DISCOVERY_METADATA).map(([path, meta]) => [
		path.toLowerCase(),
		[path, meta] as const,
	])
);

export const SdkSearchSchema = Type.Object({
	query: Type.String({
		description: `SDK method or runtime-helper discovery query. Use a namespace (e.g. 'behaviors'), one or more dotted paths separated by whitespace (e.g. 'behaviors.create ctx.sleep'), an optional client. prefix, or free text. Pass mode='read' for query_sdk-safe methods only; omit mode for your full run_sdk tier. Namespaces: ${NAMESPACES.join(", ")}.`,
		minLength: 1,
	}),
	mode: Type.Optional(
		Type.Union(
			[
				Type.Literal("read", {
					description: "Only methods callable via query_sdk (read access).",
				}),
				Type.Literal("full", {
					description:
						"Methods callable via run_sdk at your access tier (default).",
				}),
			],
			{
				description:
					"Filter results to match query_sdk ('read') or run_sdk ('full', default).",
			}
		)
	),
	limit: Type.Optional(
		Type.Number({
			description: "Max matches to return. Default 20, max 100.",
			minimum: 1,
			maximum: 100,
		})
	),
});

type SdkSearchArgs = Static<typeof SdkSearchSchema>;

export const SdkSearchResultSchema = Type.Object({
	query: Type.String({ description: "The query that was searched." }),
	match_count: Type.Integer({
		description: "Number of matches returned.",
	}),
	results: Type.Array(Type.String(), {
		description: "Rendered method-documentation strings, one per match.",
	}),
	notes: Type.Optional(
		Type.String({
			description:
				"Free-text hints (e.g. ambiguity, suggestions) when relevant.",
		})
	),
});

export type SdkSearchResult = Static<typeof SdkSearchResultSchema>;

async function agentConfigBlanketDenied(
	ctx: ToolContext,
	action: WriteAction
): Promise<boolean> {
	if (!ctx.organizationId || (!ctx.agentId && !ctx.actingWatcherId)) {
		return false;
	}
	const actor = await resolveActingPrincipal(getDb(), {
		organizationId: ctx.organizationId,
		userId: ctx.userId,
		agentId: ctx.agentId,
		sessionWatcherId: ctx.actingWatcherId ?? null,
	});
	if (actor.kind === "user") return false;
	const effect = await resolveWriteEffect({
		organizationId: ctx.organizationId,
		resourceClass: "agent_config",
		principalKind: actor.kind,
		principalId: actor.id,
		ownerAgentId: actor.ownerAgentId,
		ownerResolved: actor.ownerResolved,
		action,
		targetAgentId: null,
	});
	return effect === "deny" || effect === "disabled";
}

/** Paths hidden for this agent principal by agent_config blanket policy. */
async function deniedAgentsSdkPaths(ctx: ToolContext): Promise<Set<string>> {
	const denied = new Set<string>();
	if (!ctx.agentId && !ctx.actingWatcherId) return denied;

	const actions: WriteAction[] = ["read", "create", "update", "delete"];
	const denyByAction = new Map<WriteAction, boolean>();
	for (const action of actions) {
		denyByAction.set(action, await agentConfigBlanketDenied(ctx, action));
	}
	const allDenied = actions.every((a) => denyByAction.get(a));

	for (const [path, mapped] of Object.entries(AGENTS_SDK_ACTION)) {
		if (mapped === "any") {
			if (allDenied) denied.add(path);
			continue;
		}
		if (denyByAction.get(mapped)) denied.add(path);
	}
	return denied;
}

async function catalogForCaller(
	ctx: ToolContext,
	mode: SdkDiscoveryMode
): Promise<Array<[string, MethodMetadata]>> {
	const callerMax = resolveMaxAccessLevel(ctx.memberRole, ctx.scopes);
	const policyDenied = await deniedAgentsSdkPaths(ctx);
	return Object.entries(SDK_DISCOVERY_METADATA).filter(([path, meta]) => {
		if (!sdkMethodVisible(meta.access, callerMax, mode)) return false;
		if (policyDenied.has(path)) return false;
		return true;
	});
}

function hiddenMethodNote(
	path: string,
	meta: MethodMetadata,
	mode: SdkDiscoveryMode,
	policyDenied: Set<string>
): string {
	if (policyDenied.has(path)) {
		return `${path} is blocked by this agent's agent_config permissions.`;
	}
	if (mode === "read" && meta.access !== "read") {
		return `${path} exists but requires run_sdk (access: ${meta.access}). Retry with mode='full' or call via run_sdk.`;
	}
	if (meta.access === "admin") {
		return `${path} requires workspace admin/owner + mcp:admin.`;
	}
	return `${path} is not available at your access tier (access: ${meta.access}).`;
}

function renderListLine(path: string, meta: MethodMetadata): string {
	return `${path} — ${meta.summary}`;
}

function renderDrillDown(path: string, meta: MethodMetadata): string {
	const lines: string[] = [];
	lines.push(path);
	lines.push(`  ${meta.summary}`);
	lines.push(
		`  access: ${meta.access}${meta.cost ? ` (cost: ${meta.cost})` : ""}`
	);
	if (meta.signature) {
		lines.push(`  signature: ${meta.signature}`);
	}
	if (meta.throws && meta.throws.length > 0) {
		lines.push(`  throws: ${meta.throws.join(", ")}`);
	}
	if (meta.example) {
		lines.push(`  example: ${meta.example}`);
	}
	if (meta.usageExample) {
		lines.push("  usage_example:");
		for (const exampleLine of meta.usageExample.split("\n")) {
			lines.push(`    ${exampleLine}`);
		}
	}
	return lines.join("\n");
}

function normalizeQueryTerm(term: string): string {
	const lower = term.toLowerCase();
	return lower.startsWith("client.") ? lower.slice("client.".length) : lower;
}

export const sdkSearch = withValidatedArgs(
	"search_sdk",
	SdkSearchSchema,
	sdkSearchImpl
);

async function sdkSearchImpl(
	args: SdkSearchArgs,
	env: Env,
	ctx: ToolContext
): Promise<SdkSearchResult> {
	// Unified-catalog search (executor pattern): a query like "website" or "slack"
	// names a CONNECTOR, not an SDK method, so pure method search returns nothing
	// useful. Search live connectors and surface them (+ lifecycle) ABOVE method
	// docs. Skip the connector lookup ONLY for genuine method paths — a
	// `client.`-prefixed term, or a dotted path whose FIRST segment is a real SDK
	// namespace (`feeds.create`). A dotted CONNECTOR id (`google.calendar`) must
	// still be searched: its first segment (`google`) is not an SDK namespace.
	const q = args.query.trim();
	// NAMESPACES preserves SDK casing (entitySchema, authProfiles); the query is
	// lowercased — compare case-insensitively so `entitySchema.listTypes` is
	// recognized as a method path.
	const firstSegment = normalizeQueryTerm(q).split(".")[0];
	const isSdkNamespace = NAMESPACES.some(
		(ns) => ns.toLowerCase() === firstSegment
	);
	const looksLikeMethodPath =
		/^client\b/i.test(q) || (q.includes(".") && isSdkNamespace);
	const connectorHits = looksLikeMethodPath
		? []
		: await searchLiveConnectors(q, env, ctx);
	const methodResult = await sdkMethodSearch(args, env, ctx);
	if (connectorHits.length === 0) return methodResult;

	// Cap the COMBINED list at the same limit the method search honors, so
	// prepended connector hits can't push the response past the documented max.
	// Connector hits are the more specific answer, so they keep priority.
	const limit = Math.min(args.limit ?? 20, 100);
	const combined = [...connectorHits, ...methodResult.results];
	const results = combined.slice(0, limit);
	const dropped = combined.length - results.length;
	// When the method search found nothing, its note may carry the real answer
	// (e.g. "agents.* exists but requires admin") — losing it would leave only
	// the unrelated connector hits.
	const baseNote =
		methodResult.results.length > 0
			? "Top matches are live connectors (with lifecycle); method docs follow."
			: [
					"Matched live connectors (not SDK methods). Follow the lifecycle shown; query a namespace (e.g. 'feeds') for method signatures.",
					methodResult.notes,
				]
					.filter(Boolean)
					.join(" ");
	const truncNote =
		dropped > 0
			? ` ${dropped} more result(s) truncated; raise \`limit\` or refine the query.`
			: "";
	return {
		query: methodResult.query,
		match_count: results.length,
		results,
		notes: `${baseNote}${truncNote}`.trim(),
	};
}

async function sdkMethodSearch(
	args: SdkSearchArgs,
	_env: Env,
	ctx: ToolContext
): Promise<SdkSearchResult> {
	const limit = Math.min(args.limit ?? 20, 100);
	const query = args.query.trim();
	const terms = query
		.split(/[\s,]+/)
		.map(normalizeQueryTerm)
		.filter(Boolean);
	const lower = normalizeQueryTerm(query);
	const mode: SdkDiscoveryMode = args.mode ?? "full";
	const catalog = await catalogForCaller(ctx, mode);
	const policyDenied = await deniedAgentsSdkPaths(ctx);
	const callerMax = resolveMaxAccessLevel(ctx.memberRole, ctx.scopes);
	const isMultiMethodQuery =
		terms.length > 1 &&
		terms.every(
			(term) => term.includes(".") || METADATA_BY_LOWER_PATH.has(term)
		);

	if (isMultiMethodQuery) {
		const seen = new Set<string>();
		const matches: Array<{
			path: string;
			meta: MethodMetadata;
			exact: boolean;
		}> = [];
		const hidden: string[] = [];

		for (const term of terms) {
			const exact = METADATA_BY_LOWER_PATH.get(term);
			if (exact) {
				const [path, meta] = exact;
				if (
					!sdkMethodVisible(meta.access, callerMax, mode) ||
					policyDenied.has(path)
				) {
					hidden.push(hiddenMethodNote(path, meta, mode, policyDenied));
				} else if (!seen.has(path)) {
					seen.add(path);
					matches.push({ path, meta, exact: true });
				}
				continue;
			}

			for (const [path, meta] of catalog) {
				if (path.toLowerCase().includes(term) && !seen.has(path)) {
					seen.add(path);
					matches.push({ path, meta, exact: false });
				}
			}
			for (const [path, meta] of catalog) {
				if (meta.summary.toLowerCase().includes(term) && !seen.has(path)) {
					seen.add(path);
					matches.push({ path, meta, exact: false });
				}
			}
		}

		if (matches.length > 0) {
			return {
				query,
				match_count: matches.length,
				results: matches
					.slice(0, limit)
					.map(({ path, meta, exact }) =>
						exact ? renderDrillDown(path, meta) : renderListLine(path, meta)
					),
				notes:
					matches.length > limit
						? `${matches.length - limit} more matches; raise \`limit\` or refine the query.`
						: hidden.length > 0
							? hidden.join(" ")
							: mode === "read"
								? "Showing query_sdk-safe methods only. Pass mode='full' for write/admin methods."
								: undefined,
			};
		}

		return {
			query,
			match_count: 0,
			results: [],
			notes:
				hidden.join(" ") ||
				`No matches at your access tier. Try a namespace (${NAMESPACES.join(", ")}), mode='read' for query_sdk, or a verb (create, list, search).`,
		};
	}

	const exact = METADATA_BY_LOWER_PATH.get(lower);
	if (exact) {
		const [path, meta] = exact;
		if (
			!sdkMethodVisible(meta.access, callerMax, mode) ||
			policyDenied.has(path)
		) {
			return {
				query,
				match_count: 0,
				results: [],
				notes: hiddenMethodNote(path, meta, mode, policyDenied),
			};
		}
		return {
			query,
			match_count: 1,
			results: [renderDrillDown(path, meta)],
		};
	}

	// A namespace query whose methods are ALL hidden at this mode/tier must say
	// so by name (e.g. "agents" in mode='read') — otherwise the caller only sees
	// unrelated substring/connector matches and concludes the namespace does not
	// exist.
	let hiddenNamespaceNote: string | undefined;
	if (lower.indexOf(".") === -1) {
		// Case-insensitive like METADATA_BY_LOWER_PATH: the query is lowercased,
		// but namespaces preserve SDK casing (entitySchema, authProfiles) — a
		// case-sensitive prefix match would misreport those as hidden.
		const prefix = `${lower}.`;
		const ns = catalog.filter(([p]) => p.toLowerCase().startsWith(prefix));
		const topLevel = catalog.filter(([p]) => p.toLowerCase() === lower);
		const combined = [...topLevel, ...ns];
		if (combined.length === 0) {
			const hiddenNs = Object.entries(SDK_DISCOVERY_METADATA).filter(([p]) =>
				p.toLowerCase().startsWith(prefix)
			);
			if (hiddenNs.length > 0) {
				const accesses = [...new Set(hiddenNs.map(([, m]) => m.access))]
					.sort()
					.join(", ");
				hiddenNamespaceNote = `${lower}.* exists (${hiddenNs.length} method(s), access: ${accesses}) but none are visible${mode === "read" ? " in mode='read'" : ""} at your tier — call via run_sdk${accesses.includes("admin") ? " (admin methods need workspace admin/owner + mcp:admin)" : ""}.`;
			}
		}
		if (combined.length > 0) {
			return {
				query,
				match_count: combined.length,
				results: combined.slice(0, limit).map(([p, m]) => renderListLine(p, m)),
				notes:
					combined.length > limit
						? `${combined.length - limit} more matches; raise \`limit\` or refine the query.`
						: mode === "read"
							? "Showing query_sdk-safe methods only. Pass mode='full' for write/admin methods."
							: undefined,
			};
		}
	}

	const seen = new Set<string>();
	const matches: Array<[string, MethodMetadata]> = [];
	for (const [path, meta] of catalog) {
		if (path.toLowerCase().includes(lower) && !seen.has(path)) {
			seen.add(path);
			matches.push([path, meta]);
		}
	}
	for (const [path, meta] of catalog) {
		if (meta.summary.toLowerCase().includes(lower) && !seen.has(path)) {
			seen.add(path);
			matches.push([path, meta]);
		}
	}

	// Natural-language clients commonly search with a bag of concepts rather
	// than an exact phrase (for example "connections sync run"). Preserve the
	// precise phrase results above, then fall back to token-ranked matches so a
	// single extra word does not turn valid discovery into zero results.
	if (matches.length === 0 && terms.length > 1) {
		const ranked = catalog
			.map(([path, meta]) => {
				const pathText = path.toLowerCase();
				const summaryText = meta.summary.toLowerCase();
				const score = terms.reduce(
					(total, term) =>
						total +
						(pathText.includes(term) ? 2 : 0) +
						(summaryText.includes(term) ? 1 : 0),
					0
				);
				return { path, meta, score };
			})
			.filter((entry) => entry.score > 0)
			.sort((a, b) => b.score - a.score || a.path.localeCompare(b.path));
		for (const { path, meta } of ranked) matches.push([path, meta]);
	}

	if (matches.length === 0) {
		// Connector intent-search is handled by the sdkSearchImpl wrapper, which
		// merges live-connector hits ahead of these method results — so a
		// zero-method query like "website" still returns the connector.
		const hiddenExact = METADATA_BY_LOWER_PATH.get(lower);
		const existsButHidden = hiddenExact
			? hiddenMethodNote(hiddenExact[0], hiddenExact[1], mode, policyDenied)
			: undefined;
		return {
			query,
			match_count: 0,
			results: [],
			notes:
				hiddenNamespaceNote ??
				existsButHidden ??
				`No matches at your access tier. Try a namespace (${NAMESPACES.join(", ")}), mode='read' for query_sdk, or a verb (create, list, search).`,
		};
	}

	const tailNote =
		matches.length > limit
			? `${matches.length - limit} more matches; raise \`limit\` or refine the query.`
			: mode === "read"
				? "Showing query_sdk-safe methods only. Pass mode='full' for write/admin methods."
				: undefined;
	return {
		query,
		match_count: matches.length,
		results: matches.slice(0, limit).map(([p, m]) => renderListLine(p, m)),
		notes: hiddenNamespaceNote
			? [hiddenNamespaceNote, tailNote].filter(Boolean).join(" ")
			: tailNote,
	};
}

