			action: "connect",
			sdk_method: "connections.connect",
			arguments: [{ connector_key: operation.connector_key }],
		};
	}
	if (readiness === "disabled") {
		return {
			action: "enable_operation",
			sdk_method: "connections.update",
			arguments: [
