export interface EntityGetInput {
	entity_id?: number;
	/** Alias for `entity_id`. Accepted for ergonomics; normalized before dispatch. */
	id?: number;
	include_deleted?: boolean;
}

/**
 * Normalize the `id` alias onto `entity_id` for get/delete calls. Discovery
 * historically described these as “by id”, but the runtime field is
 * `entity_id`; accepting both removes a needless validation round-trip.
 * The stray `id` key is stripped so it never reaches the action schema.
 */
export function normalizeEntityIdInput<
	T extends { entity_id?: number; id?: number },
>(input: T): T {
	if (input.entity_id === undefined && input.id !== undefined) {
		const { id: _id, ...rest } = input;
		return { ...rest, entity_id: input.id };
	}
	return input;
}

export interface EntitiesNamespace {
	manage(input: Record<string, unknown>): Promise<unknown>;
	list(filter?: EntityListFilter): Promise<unknown>;
	get(input: EntityGetInput): Promise<unknown>;
	create(input: EntityCreateInput): Promise<unknown>;
	update(input: EntityUpdateInput): Promise<unknown>;
	delete(input: {
		entity_id?: number;
		/** Alias for `entity_id`. */
		id?: number;
		force_delete_tree?: boolean;
	}): Promise<unknown>;

