export type KnowledgeDeleteInput =
	| number
	| {
					/** Alias for `event_id` (matches `knowledge.read`'s `content_ids`). */
					content_id?: number;
					/** Alias for `event_ids` (matches `knowledge.read`'s `content_ids`). */
					content_ids?: number[];
					event_id?: number;
					event_ids?: number[];
					reason?: string;
			};

/**
 * Normalize the `content_id(s)` aliases used by `knowledge.read` onto the
 * `event_id(s)` fields the delete tool actually accepts. Without this, the
 * analogous delete call (`knowledge.delete({ content_ids })`) is rejected as
 * unknown arguments even though read accepts the same shape.
 */
export function normalizeKnowledgeDeleteInput<
	T extends {
		content_id?: number;
		content_ids?: number[];
		event_id?: number;
		event_ids?: number[];
		reason?: string;
	},
>(input: T): T {
	const { content_id, content_ids, ...rest } = input;
	if (rest.event_id === undefined && rest.event_ids === undefined) {
		if (content_id !== undefined) rest.event_id = content_id;
		else if (content_ids !== undefined) rest.event_ids = content_ids;
	}
	return rest;
}

