/**
 * `attribute_values` MUST be a keyed object (Record<optionValue, config>),
 * never an array. TypeBox's `Type.Record(Type.String(), …)` accepts JS
 * arrays — arrays are objects with string-coerced numeric keys — so an array
 * payload slipped through schema validation and was silently corrupted into
 * `{"0": {}, "1": {}}` by the `Object.entries` hydration/strip paths
 * (issue #2033, bug #4). This guard is the authoritative shape check.
 */
export function isValidAttributeValuesShape(
  values: unknown
): values is Record<string, unknown> {
  return typeof values === 'object' && values !== null && !Array.isArray(values);
}

function stripEmbeddingsFromAttributeValues(
  attributeValues: unknown
): Record<string, { description: string; examples: string[] }> | null {
  if (!attributeValues) return null;
  // Arrays are rejected authoritatively at write time, but defend the read
  // path too: Object.entries on an array yields {"0":…, "1":…} keys, which is
  // exactly the corruption reported. Never coerce — surface nothing instead.
  if (Array.isArray(attributeValues)) return null;
  const parsed =
    typeof attributeValues === 'string' ? JSON.parse(attributeValues) : attributeValues;
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) return null;

