import { describe, expect, it } from "bun:test";
import {
	isValidAttributeValuesShape,
	// biome-ignore lint/correctness/noUnusedImports: type-only re-export check
	type stripEmbeddingsFromAttributeValues as _stripType,
} from "../../../tools/admin/manage_classifiers";
// `stripEmbeddingsFromAttributeValues` is module-internal; exercised via the
// exported shape guard + a mirror of its array-defense contract below.
import { normalizeEntityIdInput } from "../../../sandbox/namespaces/entities";
import { normalizeKnowledgeDeleteInput } from "../../../sandbox/namespaces/knowledge";

describe("issue #2033 — SDK contract aliases", () => {
	describe("entities.get/delete accept `id` as an alias for `entity_id` (bug #6)", () => {
		it("maps a lone `id` onto `entity_id` and strips the alias", () => {
			expect(normalizeEntityIdInput({ id: 42 })).toEqual({ entity_id: 42 });
		});

		it("preserves sibling fields when mapping the alias", () => {
			expect(
				normalizeEntityIdInput({ id: 42, include_deleted: true }),
			).toEqual({ entity_id: 42, include_deleted: true });
		});

		it("leaves an explicit `entity_id` untouched (no stray `id` in output)", () => {
			const out = normalizeEntityIdInput({ entity_id: 7 });
			expect(out).toEqual({ entity_id: 7 });
			expect("id" in out).toBe(false);
		});

		it("does not invent `entity_id` when neither is present", () => {
			expect(normalizeEntityIdInput({})).toEqual({});
		});
	});

	describe("knowledge.delete accepts content_id(s) aliases matching knowledge.read (bug #7)", () => {
		it("maps `content_ids` → `event_ids` and carries `reason`", () => {
			expect(
				normalizeKnowledgeDeleteInput({
					content_ids: [1, 2, 3],
					reason: "cleanup",
				}),
			).toEqual({ event_ids: [1, 2, 3], reason: "cleanup" });
		});

		it("maps a singular `content_id` → `event_id`", () => {
			expect(normalizeKnowledgeDeleteInput({ content_id: 9 })).toEqual({
				event_id: 9,
			});
		});

		it("leaves explicit `event_id(s)` untouched (canonical wins over alias)", () => {
			expect(
				normalizeKnowledgeDeleteInput({ event_id: 1, content_id: 2 }),
			).toEqual({ event_id: 1 });
			expect(
				normalizeKnowledgeDeleteInput({ event_ids: [1], content_ids: [2] }),
			).toEqual({ event_ids: [1] });
		});

		it("strips the alias keys even when no canonical field is produced", () => {
			const out = normalizeKnowledgeDeleteInput({ content_id: undefined });
			expect("content_id" in out).toBe(false);
			expect("event_id" in out).toBe(false);
		});
	});

	describe("classifier attribute_values round-trip (bug #4)", () => {
		it("accepts a keyed object of option → config", () => {
			expect(
				isValidAttributeValuesShape({
					high: { description: "high intent", examples: ["a"] },
				}),
			).toBe(true);
		});

		it.each([
			["array", [{ description: "x", examples: [] }]],
			["null", null],
			["string", "high"],
			["number", 1],
		])("rejects a non-object %s payload", (_label, value) => {
			expect(isValidAttributeValuesShape(value)).toBe(false);
		});

		it("the array-rejection guards against the {0:{},1:{}} corruption shape", () => {
			// This is exactly what the production read-back returned: an array of
			// (mostly embedding-only) objects coerced into {0:{},1:{}}.
			const corruptedShape = [
				{ embedding: [0.1, 0.2] },
				{ embedding: [0.3, 0.4] },
			];
			expect(isValidAttributeValuesShape(corruptedShape)).toBe(false);
		});
	});
});

