import {
	AgentWatcherBehaviorRoute,
	type WatcherBehaviorView,
} from "@/components/agents/agent-watchers-route";
import { parseRunId } from "@/components/agents/config-prefill";

function parseView(value: unknown): WatcherBehaviorView {
	return value === "activity" ? "activity" : "definition";
}

export const Route = createFileRoute(
	"/$owner/agents/$agentId/behaviors/$watcherId",
)({
	validateSearch: (search: Record<string, unknown>) => ({
		// Slack config-approval deep link: `?run_id=42` reviews the held builder
		// manage_behaviors proposal (Approve/Reject) instead of a plain edit.
		run_id: parseRunId(search.run_id),
		view: parseView(search.view),
	}),
	component: AgentBehaviorWatcherPage,
});

function AgentBehaviorWatcherPage() {
	const { owner, agentId, watcherId } = Route.useParams();
	const search = Route.useSearch();
	return (
		<AgentWatcherBehaviorRoute
			owner={owner}
			agentId={agentId}
			watcherId={watcherId}
			runId={search.run_id}
			view={search.view}
		/>
	);
}
