/**
 * Public/product terminology → canonical SDK namespace. Lets callers discover
 * methods under the user-facing name even after a rename. Keys are matched
 * case-insensitively against a single dotless query term.
 */
const NAMESPACE_ALIASES: Record<string, string> = {
	watchers: "behaviors",
	watcher: "behaviors",
};

	// Public-terminology alias (e.g. 'watchers' → 'behaviors'): the query did
	// not match a namespace directly, but a documented product term maps to a
	// real SDK namespace. Surface that namespace's methods plus a migration
	// note instead of returning a dead end.
	const aliasCanonical = NAMESPACE_ALIASES[lower];
	if (aliasCanonical) {
		const aliasPrefix = `${aliasCanonical}.`;
		const aliasNs = catalog.filter(([p]) =>
			p.toLowerCase().startsWith(aliasPrefix),
		);
		if (aliasNs.length > 0) {
			return {
				query,
				match_count: aliasNs.length,
				results: aliasNs.slice(0, limit)
					.map(([p, m]) => renderListLine(p, m)),
				notes: `'${lower}' is the public term for the '${aliasCanonical}' SDK namespace — use client.${aliasCanonical} (e.g. client.${aliasCanonical}.list / .get / .trigger).`,
			};
		}
	}
}

